// 합성이 안전하다
class Square { constructor(private side: number) {} area() { return this.side ** 2; } }

class Player {
  constructor(private mover: Mover, private attacker: Attacker) {}
  update(dt: number) { this.mover.move(dt); }
  attack() { this.attacker.attack(); }
}
